import type {
  AgendaAvailability,
  AgendaAvailabilitySlot,
} from "@/types/agendaBooking";

const inputClass =
  "w-full rounded-xl border border-gray-200 supplier-surface-card bg-[var(--supplier-card-background,#ffffff)] px-4 py-3 outline-none transition focus:border-[var(--supplier-outline,#168e00)] focus:ring-2 focus:ring-[var(--supplier-outline,#168e00)]/10 disabled:cursor-not-allowed disabled:bg-gray-50 disabled:text-gray-400";

function todayInput() {
  const now = new Date();
  const local = new Date(
    now.getTime() - now.getTimezoneOffset() * 60000,
  );
  return local.toISOString().slice(0, 10);
}

function startOfMonthInput(dateInput: string) {
  return `${dateInput.slice(0, 7)}-01`;
}

function endOfMonthInput(monthInput: string) {
  const [year, month] = monthInput.split("-").map(Number);
  return new Date(Date.UTC(year, month, 0, 12))
    .toISOString()
    .slice(0, 10);
}

function addMonthsToInput(monthInput: string, months: number) {
  const [year, month] = monthInput.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1 + months, 1, 12));
  return date.toISOString().slice(0, 10);
}

function formatMoney(value: number | null) {
  if (value == null) return "Consultar precio";

  return new Intl.NumberFormat("es-MX", {
    style: "currency",
    currency: "MXN",
  }).format(value);
}

function formatSlot(
  iso: string,
  timezone: string,
) {
  return new Intl.DateTimeFormat("es-MX", {
    timeZone: timezone,
    hour: "2-digit",
    minute: "2-digit",
    hour12: true,
  }).format(new Date(iso));
}

function formatDate(
  dateValue: string,
) {
  const [year, month, day] = dateValue.split("-").map(Number);

  return new Intl.DateTimeFormat("es-MX", {
    dateStyle: "full",
    timeZone: "UTC",
  }).format(new Date(Date.UTC(year, month - 1, day, 12)));
}

function nextPaymentMethod(
  data: AgendaAvailability,
  current: AgendaPaymentMethod,
): AgendaPaymentMethod {
  if (!data.accepts_payments) return "none";
  const cashAvailable = data.allows_cash_payment;
  const onlineAvailable = data.online_payment_available;
  if (current === "cash" && cashAvailable) return current;
  if (current === "online" && onlineAvailable) return current;
  if (cashAvailable && !onlineAvailable) return "cash";
  if (onlineAvailable && !cashAvailable) return "online";
  return "none";
}

export default function PublicAgendaBookingPage() {
  const params = useParams<{ supplierId: string }>();
  const router = useRouter();
  const hydrated = useAuthHydrated();

  const auth = useAuthStore();
  const supplierId = Number(params.supplierId);
  const [portalTheme, setPortalTheme] = useState<{ supplierId: number; colors: SupplierThemeSource } | null>(null);
  const themeSource = portalTheme?.supplierId === supplierId ? portalTheme.colors : {};
  const [loginReturnTo, setLoginReturnTo] = useState(
    `/agenda/${params.supplierId}`,
  );

  const [services, setServices] = useState<AgendaService[]>([]);
  const [savedPublicTitle, setSavedPublicTitle] = useState<string | null>(null);
  const [businessType, setBusinessType] = useState<AgendaBusinessType | null>(null);
  const [selectedServiceId, setSelectedServiceId] = useState<number | null>(
    null,
  );
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [visibleMonth, setVisibleMonth] = useState(() =>
    startOfMonthInput(todayInput()),
  );
  const [calendarMinDate, setCalendarMinDate] = useState(todayInput);
  const [calendarMaxDate, setCalendarMaxDate] = useState<string | null>(null);
  const [availability, setAvailability] =
    useState<AgendaAvailability | null>(null);
  const [selectedSlot, setSelectedSlot] =
    useState<AgendaAvailabilitySlot | null>(null);

  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [notes, setNotes] = useState("");
  const [paymentMethod, setPaymentMethod] =
    useState<AgendaPaymentMethod>("none");
  const selectedPaymentMethod = availability
    ? nextPaymentMethod(availability, paymentMethod)
    : "none";

  const [loadingServices, setLoadingServices] = useState(true);
  const [loadingSlots, setLoadingSlots] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [availabilityRefresh, setAvailabilityRefresh] = useState(0);
  const [quoteState, setQuoteState] = useState<{ serviceId: number; quote: FinancialQuote | null; legacy: boolean; error: string }>({ serviceId: 0, quote: null, legacy: false, error: '' });
  const [quoteRefresh, setQuoteRefresh] = useState(0);
  const [acceptedTerms, setAcceptedTerms] = useState(false);
  type BookingAttempt = { supplierId: number; payload: FinancialBookingPayload; bookingId?: number; checkout?: string; managementToken?: string; requiresTermsReview?: boolean };
  const financialAttempt = useRef<BookingAttempt | null>(null);
  const attemptScope = `booking:${supplierId}:${auth.isAuthenticated ? auth.user?.id : 'guest'}`;
  const [legacyUncertain, setLegacyUncertain] = useState(false);
  const [recoveringAttempt, setRecoveringAttempt] = useState(false);
  useEffect(() => {
    if (!hydrated) return;
    try {
      financialAttempt.current = readFinancialAttempt<BookingAttempt>(attemptScope);
      setRecoveringAttempt(Boolean(financialAttempt.current));
      if (financialAttempt.current?.requiresTermsReview) setSelectedServiceId(financialAttempt.current.payload.service_id);
      setLegacyUncertain(Boolean(readFinancialAttempt<boolean>(`${attemptScope}:legacy`)));
    } catch { setError("No se pudo recuperar el intento pendiente. Revisa tus citas antes de continuar."); }
  }, [attemptScope, hydrated]);
  const quote = quoteState.serviceId === selectedServiceId ? quoteState.quote : null;
  const legacy = quoteState.serviceId === selectedServiceId && quoteState.legacy;
  const savingRef = useRef(false);
  const createdBookingId = useRef<number | null>(null);
  const lastVisibilityRefresh = useRef(0);
  const timezoneAligned = useRef(false);
  const calendarBounds = useRef<{ min: string; max: string | null }>({
    min: todayInput(),
    max: null,
  });

  useEffect(() => {
    setLoginReturnTo(getBrowserPathWithSearchAndHash());
  }, [supplierId]);

  useEffect(() => {
    if (!Number.isFinite(supplierId) || supplierId <= 0) return;
    const controller = new AbortController();

    void Promise.allSettled([
      agendaBookingService.getPublicSettings(supplierId, controller.signal),
      fetch(`/proxy/suppliers/${supplierId}`, { signal: controller.signal, cache: "no-store" })
        .then((response) => response.ok ? response.json() : null),
    ]).then(([settingsResult, supplierResult]) => {
      if (controller.signal.aborted) return;
      const supplierPayload = supplierResult.status === "fulfilled" ? supplierResult.value : null;
      const supplierRecord = supplierPayload && typeof supplierPayload === "object"
        ? supplierPayload as Record<string, unknown> : null;
      const supplier = supplierRecord?.supplier && typeof supplierRecord.supplier === "object"
        ? supplierRecord.supplier as Record<string, unknown> : supplierRecord;
      setPortalTheme({ supplierId, colors: (supplier ?? {}) as SupplierThemeSource });
      const type = supplier?.business_type;
      if (typeof type === "string") {
        setBusinessType(type);
      } else if (type && typeof type === "object") {
        const candidate = type as Record<string, unknown>;
        setBusinessType({
          name: typeof candidate.name === "string" ? candidate.name : null,
          slug: typeof candidate.slug === "string" ? candidate.slug : null,
          title: typeof candidate.title === "string" ? candidate.title : null,
          label: typeof candidate.label === "string" ? candidate.label : null,
        });
      }
      const supplierSettings = supplier?.agenda_settings;
      const supplierTitle = supplierSettings && typeof supplierSettings === "object"
        ? (supplierSettings as Record<string, unknown>).public_booking_title : null;
      const settingsTitle = settingsResult.status === "fulfilled"
        ? settingsResult.value.public_booking_title : null;
      const title = settingsTitle || supplierTitle;
      if (typeof title === "string" && title.trim()) setSavedPublicTitle(title);
    });

    return () => controller.abort();
  }, [supplierId]);

  const selectedService = useMemo(
    () =>
      services.find((service) => service.id === selectedServiceId) ??
      null,
    [services, selectedServiceId],
  );

  const guestBlocked =
    hydrated &&
    !auth.isAuthenticated &&
    availability?.allow_guest_bookings === false;

  const guestEmailRequired =
    !auth.isAuthenticated &&
    (availability?.require_guest_email ?? true);

  const slotsByDate = useMemo(() => {
    const grouped = new Map<string, AgendaAvailabilitySlot[]>();

    if (!availability) return grouped;

    availability.slots.forEach((slot) => {
      const date = dateInputInTimeZone(
        slot.start_at,
        availability.timezone,
      );
      if (!date) return;

      const current = grouped.get(date);
      if (current) current.push(slot);
      else grouped.set(date, [slot]);
    });

    return grouped;
  }, [availability]);

  const availableDates = useMemo(
    () => new Set(slotsByDate.keys()),
    [slotsByDate],
  );

  const selectedDateSlots = selectedDate
    ? slotsByDate.get(selectedDate) ?? []
    : [];

  useEffect(() => {
    if (!Number.isFinite(supplierId) || supplierId <= 0) {
      setError("Proveedor inválido.");
      setLoadingServices(false);
      return;
    }

    const controller = new AbortController();

    const run = async () => {
      try {
        setError(null);

        const data =
          await agendaBookingService.listPublicServices(
            supplierId,
            controller.signal,
          );
        if (controller.signal.aborted) return;

        setServices(data);

        if (data.length) {
          const pendingService = financialAttempt.current?.payload.service_id;
          setSelectedServiceId(pendingService && data.some(service => service.id === pendingService) ? pendingService : data[0].id);
        }
      } catch (err) {
        if (isExpectedAbort(err, controller.signal)) return;
        setError(
          err instanceof Error
            ? err.message
            : "No se pudo cargar la agenda.",
        );
      } finally {
        if (!controller.signal.aborted) setLoadingServices(false);
      }
    };

    void run();

    return () => controller.abort();
  }, [supplierId]);

  useEffect(() => {
    const refreshAfterReturn = () => {
      if (document.visibilityState !== "visible" || !selectedServiceId) return;
      const now = Date.now();
      if (now - lastVisibilityRefresh.current < 15_000) return;
      lastVisibilityRefresh.current = now;
      setAvailabilityRefresh((current) => current + 1);
    };
    const onPageShow = (event: PageTransitionEvent) => {
      if (!event.persisted) return;
      createdBookingId.current = null;
      setSelectedSlot(null);
      lastVisibilityRefresh.current = 0;
      refreshAfterReturn();
    };
    document.addEventListener("visibilitychange", refreshAfterReturn);
    window.addEventListener("pageshow", onPageShow);
    return () => {
      document.removeEventListener("visibilitychange", refreshAfterReturn);
      window.removeEventListener("pageshow", onPageShow);
    };
  }, [selectedServiceId]);

  useEffect(() => {
    if (!hydrated) return;

    if (auth.user) {
      setName((current) => current || auth.user?.name || "");
      setEmail((current) => current || auth.user?.email || "");
    }
  }, [hydrated, auth.user]);

  useEffect(() => {
    const monthEnd = endOfMonthInput(visibleMonth);
    const dateFrom =
      visibleMonth < calendarBounds.current.min
        ? calendarBounds.current.min
        : visibleMonth;
    const dateTo =
      calendarBounds.current.max && calendarBounds.current.max < monthEnd
        ? calendarBounds.current.max
        : monthEnd;

    if (!selectedServiceId || dateTo < dateFrom) {
      setAvailability(null);
      setSelectedDate(null);
      setSelectedSlot(null);
      return;
    }

    const controller = new AbortController();

    const run = async () => {
      setLoadingSlots(true);

      try {
        const data =
          await agendaBookingService.availability(
            supplierId,
            selectedServiceId,
            dateFrom,
            dateTo,
            controller.signal,
          );
        if (controller.signal.aborted) return;

        if (data.public_booking_title?.trim()) {
          setSavedPublicTitle(data.public_booking_title);
        }

        const providerToday =
          dateInputInTimeZone(new Date(), data.timezone) || todayInput();
        const providerMaxDate = addDaysToDateInput(
          providerToday,
          data.maximum_booking_days,
        );

        calendarBounds.current = {
          min: providerToday,
          max: providerMaxDate,
        };
        setCalendarMinDate((current) =>
          current === providerToday ? current : providerToday,
        );
        setCalendarMaxDate((current) =>
          current === providerMaxDate ? current : providerMaxDate,
        );
        setAvailability(data);
        setSelectedSlot((current) => current &&
          data.slots.some((slot) => slot.start_at === current.start_at)
            ? data.slots.find((slot) => slot.start_at === current.start_at) ?? null
            : null);
        setPaymentMethod((current) => nextPaymentMethod(data, current));

        if (!timezoneAligned.current) {
          timezoneAligned.current = true;
          const providerMonth = startOfMonthInput(providerToday);
          if (providerMonth !== visibleMonth) {
            setVisibleMonth(providerMonth);
            setSelectedDate(null);
            return;
          }
        }

        const grouped = new Map<string, AgendaAvailabilitySlot[]>();
        data.slots.forEach((slot) => {
          const date = dateInputInTimeZone(slot.start_at, data.timezone);
          if (!date) return;
          const current = grouped.get(date);
          if (current) current.push(slot);
          else grouped.set(date, [slot]);
        });

        setSelectedDate((current) => {
          if (current && grouped.has(current)) return current;
          if (grouped.has(providerToday)) return providerToday;
          return grouped.keys().next().value ?? null;
        });
      } catch (err) {
        if (isExpectedAbort(err, controller.signal)) return;
        setAvailability(null);
        setSelectedDate(null);
        setSelectedSlot(null);
        setError(
          err instanceof Error
            ? err.message
            : "No se pudieron consultar los horarios.",
        );
      } finally {
        if (!controller.signal.aborted) {
          setLoadingSlots(false);
        }
      }
    };

    void run();

    return () => controller.abort();
  }, [
    availabilityRefresh,
    supplierId,
    selectedServiceId,
    visibleMonth,
  ]);

  useEffect(() => {
    if (!selectedServiceId) return;
    const controller = new AbortController();
    setAcceptedTerms(false);
    setQuoteState({ serviceId: selectedServiceId, quote: null, legacy: false, error: '' });
    void agendaBookingService.financialQuote(supplierId, selectedServiceId, controller.signal).then(data => {
      if (!controller.signal.aborted) setQuoteState({ serviceId: selectedServiceId, quote: data, legacy: false, error: '' });
    }).catch(err => {
      if (isExpectedAbort(err, controller.signal)) return;
      const disabled = err instanceof AgendaBookingRequestError && err.status === 409 && err.message === 'Los pagos ampliados de Agenda aún no están habilitados.';
      setQuoteState({ serviceId: selectedServiceId, quote: null, legacy: disabled, error: disabled ? 'Los anticipos aún no están habilitados. Se aplican las formas de reserva tradicionales disponibles.' : err instanceof Error ? err.message : 'No se pudo consultar el pago inicial.' });
    });
    return () => controller.abort();
  }, [supplierId, selectedServiceId, quoteRefresh]);

  const submitFinancial = async () => {
    if (savingRef.current) return;
    try {
      const stored = readFinancialAttempt<BookingAttempt>(attemptScope);
      if (stored) { financialAttempt.current = stored; setRecoveringAttempt(true); }
      if (financialAttempt.current?.bookingId) {
        const previous = financialAttempt.current;
        router.push(`/agenda/bookings/${previous.bookingId}${previous.managementToken ? `?management_token=${encodeURIComponent(previous.managementToken)}` : ""}`);
        clearFinancialAttempt(attemptScope);
        return;
      }
    } catch { setError('Permite el almacenamiento de sesión para recuperar el mismo intento de reserva de forma segura.'); return; }
    if (createdBookingId.current !== null) return;
    const recoveringCreation = Boolean(financialAttempt.current);
    if (!financialAttempt.current) {
      if (!quote || !selectedSlot || !availability || !name.trim() || guestBlocked) { setError('Completa los datos de la reservación.'); return; }
      if (!bookingTermsPayload(quote, acceptedTerms)) { setError('Acepta expresamente las condiciones antes de reservar.'); return; }
      if ((guestEmailRequired || (cents(quote.initial_required) ?? BigInt(0)) > BigInt(0)) && !email.trim()) { setError('Escribe tu correo electrónico para reservar.'); return; }
    }
    const reviewing = financialAttempt.current?.requiresTermsReview;
    if (reviewing) {
      const attempt = financialAttempt.current!;
      const payload = quote ? refreshRejectedBookingTerms(attempt.payload, quote, acceptedTerms) : null;
      if (!payload) { setError('Revisa y acepta las condiciones actualizadas antes de continuar.'); return; }
      financialAttempt.current = { ...attempt, payload, requiresTermsReview: false };
    }
    savingRef.current = true; setSaving(true); setError(null);
    try {
      if (!financialAttempt.current && quote && selectedSlot && availability && selectedService) {
        const date = dateInputInTimeZone(selectedSlot.start_at, availability.timezone);
        if (!date) throw new Error('Selecciona un horario válido.');
        const latest = await agendaBookingService.availability(supplierId, selectedService.id, date, date);
        if (!latest.slots.some(slot => slot.start_at === selectedSlot.start_at)) throw new Error('Ese horario ya no está disponible. Selecciona otro.');
        financialAttempt.current = { supplierId, payload: { service_id: selectedService.id, start_at: selectedSlot.start_at, customer_name: name.trim(), customer_email: email.trim() || null, customer_phone: phone.trim() || null, notes: notes.trim() || null, idempotency_key: crypto.randomUUID(), ...bookingTermsPayload(quote, acceptedTerms) } };
      }
      const attempt = financialAttempt.current;
      if (!attempt) return;
      writeFinancialAttempt(attemptScope, attempt);
      const result = await agendaBookingService.createFinancialBooking(attempt.supplierId, attempt.payload);
      const booking = result.booking;
      const checkout = !recoveringCreation && result.financial.payment_state === "not_started" && result.payment_intent?.status === "ready" ? getSafeMercadoPagoUrl(result.payment_intent.checkout_url) : "";
      writeFinancialAttempt(attemptScope, { ...attempt, bookingId: booking.id, checkout, managementToken: booking.management_token });
      createdBookingId.current = booking.id;
      try { window.localStorage.setItem(`agenda-management-${booking.id}`, booking.management_token); } catch { /* Guest access is also preserved in the management link. */ }
      clearFinancialAttempt(attemptScope);
      if (checkout) { window.location.assign(checkout); return; }
      // Never create another intent when Checkout creation is pending or uncertain.
      router.push(`/agenda/bookings/${booking.id}${auth.isAuthenticated ? '' : `?management_token=${encodeURIComponent(booking.management_token)}`}`);
    } catch (err) {
      if (isTermsVersionError(err) && financialAttempt.current) {
        const attempt = { ...financialAttempt.current, requiresTermsReview: true };
        financialAttempt.current = attempt;
        writeFinancialAttempt(attemptScope, attempt);
        setAcceptedTerms(false);
        setSelectedServiceId(attempt.payload.service_id);
        setQuoteState({ serviceId: attempt.payload.service_id, quote: null, legacy: false, error: '' });
        setQuoteRefresh(current => current + 1);
        setError('Las condiciones cambiaron. Revisa la nueva cotización y acepta las condiciones vigentes antes de confirmar nuevamente.');
        return;
      }
      setError(`${err instanceof Error ? err.message : 'No pudimos confirmar la reservación.'}${financialAttempt.current ? ' Se conserva el mismo intento. Reintentar no creará una segunda reservación.' : ''}`);
    } finally { savingRef.current = false; setSaving(false); }
  };

  const submit = async () => {
    try { financialAttempt.current = financialAttempt.current ?? readFinancialAttempt<BookingAttempt>(attemptScope); }
    catch { setError('No se pudo recuperar el intento de reserva. Revisa tus citas antes de continuar.'); return; }
    if (financialAttempt.current || quote) { await submitFinancial(); return; }
    if (!legacy) { setError("Consulta el pago inicial antes de reservar."); return; }
    if (legacyUncertain || readFinancialAttempt<boolean>(`${attemptScope}:legacy`)) { setError("Hay una reservación tradicional con resultado incierto. Revisa tus citas o el correo de confirmación antes de solicitar otra al establecimiento."); return; }
    if (savingRef.current || createdBookingId.current !== null) return;
    if (!selectedService || !selectedSlot || !availability) {
      setError("Selecciona servicio, fecha y horario.");
      return;
    }

    if (guestBlocked) {
      setError(
        "Este negocio no permite reservaciones como invitado. Inicia sesión para continuar.",
      );
      return;
    }

    if (!name.trim()) {
      setError("Escribe el nombre de la persona que asistirá.");
      return;
    }

    if (guestEmailRequired && !email.trim()) {
      setError(
        "Este negocio solicita correo a los invitados para enviar la confirmación y el enlace de administración de la cita.",
      );
      return;
    }

    if (availability?.accepts_payments && selectedPaymentMethod === "none") {
      setError("Selecciona una forma de pago para reservar.");
      return;
    }

    savingRef.current = true;
    setSaving(true);
    setError(null);
    let creating = false;

    try {
      const slotDate = dateInputInTimeZone(
        selectedSlot.start_at,
        availability.timezone,
      );
      if (!slotDate) {
        setError("No pudimos confirmar ese horario. Elige otro.");
        return;
      }
      const latest = await agendaBookingService.availability(
        supplierId,
        selectedService.id,
        slotDate,
        slotDate,
      );
      if (!latest.slots.some((slot) => slot.start_at === selectedSlot.start_at)) {
        setSelectedSlot(null);
        setAvailabilityRefresh((current) => current + 1);
        setError("Ese horario acaba de dejar de estar disponible. Elige otro.");
        return;
      }
      if (selectedPaymentMethod === "online" && !latest.online_payment_available) {
        setPaymentMethod(latest.allows_cash_payment ? "cash" : "none");
        setAvailabilityRefresh((current) => current + 1);
        setError("El pago en línea ya no está disponible. Selecciona otra forma de pago.");
        return;
      }

      creating = true;
      writeFinancialAttempt(`${attemptScope}:legacy`, true);
      setLegacyUncertain(true);
      const booking =
        await agendaBookingService.createBooking(
          supplierId,
          {
            service_id: selectedService.id,
            start_at: selectedSlot.start_at,
            customer_name: name.trim(),
            customer_email: email.trim() || null,
            customer_phone: phone.trim() || null,
            notes: notes.trim() || null,
            payment_method: availability?.accepts_payments
              ? selectedPaymentMethod
              : "none",
          },
        );
      createdBookingId.current = booking.id;
      clearFinancialAttempt(`${attemptScope}:legacy`);
      setLegacyUncertain(false);

      if (typeof window !== "undefined") {
        window.localStorage.setItem(
          `agenda-management-${booking.id}`,
          booking.management_token,
        );
      }

      if (booking.payment_method === "online") {
        const checkoutUrl = getSafeMercadoPagoUrl(booking.payment_checkout_url);
        if (!checkoutUrl) {
          setError("No se pudo iniciar el pago. Intenta nuevamente.");
          return;
        }
        window.location.assign(checkoutUrl);
        return;
      }

      const query = auth.isAuthenticated
        ? ""
        : `?management_token=${encodeURIComponent(booking.management_token)}`;

      router.push(
        `/agenda/bookings/${booking.id}${query}`,
      );
    } catch (err) {
      if (err instanceof AgendaBookingRequestError && err.status >= 400 && err.status < 500 && err.status !== 408) { clearFinancialAttempt(`${attemptScope}:legacy`); setLegacyUncertain(false); }
      if (createdBookingId.current !== null) {
        setError("Tu reservación fue creada, pero no pudimos actualizar algunos detalles. Puedes intentarlo nuevamente desde tu cita.");
        return;
      }
      const message = isHttpConflict(err)
        ? "Ese horario acaba de dejar de estar disponible. Elige otro."
        : !creating
          ? "No pudimos actualizar los horarios. Intenta nuevamente antes de reservar."
          : err instanceof Error ? err.message : "No se pudo crear la cita.";

      setError(message);

      if (
        message ===
        "Ese horario acaba de dejar de estar disponible. Elige otro."
      ) {
        setSelectedSlot(null);
        setAvailabilityRefresh((current) => current + 1);
      }
    } finally {
      savingRef.current = false;
      setSaving(false);
    }
  };

  if (loadingServices) {
    return (
      <SupplierTheme supplier={themeSource} className="flex min-h-[60vh] items-center justify-center">
        <Loader2
          className="animate-spin text-[var(--supplier-accent,#168e00)]"
          size={36}
        />
      </SupplierTheme>
    );
  }

  if (!services.length) {
    return (
      <SupplierTheme supplier={themeSource}><main className="mx-auto max-w-3xl px-4 pb-24 pt-28 sm:pb-12 sm:pt-32">
        <div className="rounded-3xl border border-gray-100 supplier-surface-card bg-[var(--supplier-card-background,#ffffff)] p-8 text-center shadow-sm">
          <CalendarDays
            className="mx-auto text-[var(--supplier-accent,#168e00)]"
            size={42}
          />
          <h1 className="mt-4 text-2xl font-bold text-gray-900">
            Agenda no disponible
          </h1>
          <p className="mt-2 text-gray-500">
            Este negocio no tiene servicios disponibles para reservar
            en este momento.
          </p>
        </div>
      </main></SupplierTheme>
    );
  }

  return (
    <SupplierTheme supplier={themeSource}><main className="mx-auto max-w-5xl space-y-6 px-4 pb-24 pt-28 sm:pb-12 sm:pt-32">
      <div>
        <button
          type="button"
          onClick={() => router.back()}
          className="inline-flex items-center gap-2 text-sm font-semibold text-gray-500 hover:text-[var(--supplier-heading,#004e28)]"
        >
          <ArrowLeft size={17} />
          Volver
        </button>
      </div>

      <section className="rounded-3xl supplier-surface-secondary bg-[var(--supplier-secondary,#004e28)] p-6 text-[color:var(--supplier-inverse,#ffffff)] sm:p-8">
        <div className="flex items-start gap-4">
          <div className="rounded-2xl bg-[var(--supplier-card-background,#ffffff)]/10 p-3">
            <CalendarDays size={30} />
          </div>
          <div>
            <p className="text-sm font-semibold text-[color:var(--supplier-inverse-muted,#ffffff)]">
              Agenda
            </p>
            <h1 className="mt-1 text-3xl font-bold">
              {publicAgendaTitle(savedPublicTitle, businessType)}
            </h1>
            <p className="mt-2 max-w-2xl text-sm text-[color:var(--supplier-inverse-muted,#ffffff)]">
              Elige el servicio, la fecha y uno de los horarios
              disponibles.
            </p>
          </div>
        </div>
      </section>

      {error ? (
        <div
          className="rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700"
          role="alert"
        >
          {error}
        </div>
      ) : null}

    {availability ? (
  <section className="rounded-3xl border border-[var(--supplier-outline,#168e00)]/15 bg-[var(--supplier-primary,#168e00)]/5 p-5">
    <div className="flex items-start gap-3">
      <Info
        className="mt-0.5 shrink-0 text-[var(--supplier-accent,#168e00)]"
        size={20}
      />

      <div>
        <h2 className="font-bold text-[var(--supplier-heading,#004e28)]">
          Reglas de reservación
        </h2>

        <div className="mt-2 space-y-1 text-sm text-gray-700">
          <p>
            Reserva con al menos{" "}
            <strong>
              {humanizeMinutes(
                availability.minimum_notice_minutes,
              )}
            </strong>{" "}
            de anticipación.
          </p>

          <p>
            Puedes reservar hasta{" "}
            <strong>
              {humanizeDays(
                availability.maximum_booking_days,
              )}
            </strong>{" "}
            hacia adelante.
          </p>

          {!auth.isAuthenticated ? (
            <p>
              {availability.allow_guest_bookings
                ? availability.require_guest_email
                  ? "Se permiten reservaciones como invitado y el correo es obligatorio."
                  : "Se permiten reservaciones como invitado."
                : "Para reservar debes iniciar sesión."}
            </p>
          ) : null}
        </div>
      </div>
    </div>
  </section>
) : null}

      {guestBlocked ? (
        <section className="rounded-3xl border border-amber-200 bg-amber-50 p-5">
          <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center">
            <div className="flex items-start gap-3">
              <ShieldAlert
                className="mt-0.5 shrink-0 text-amber-700"
                size={22}
              />
              <div>
                <h2 className="font-bold text-amber-900">
                  Este negocio requiere una cuenta
                </h2>
                <p className="mt-1 text-sm text-amber-800">
                  Las reservaciones como invitado están desactivadas.
                  Inicia sesión para poder confirmar la cita.
                </p>
              </div>
            </div>

            <Link
              href={getLoginUrl(loginReturnTo)}
              className="inline-flex shrink-0 items-center justify-center gap-2 rounded-xl bg-amber-700 px-4 py-2.5 font-semibold text-[color:var(--supplier-inverse,#ffffff)]"
            >
              <LogIn size={18} />
              Iniciar sesión
            </Link>
          </div>
        </section>
      ) : !auth.isAuthenticated && hydrated ? (
        <section className="rounded-3xl border border-[var(--supplier-outline,#168e00)]/20 bg-[var(--supplier-primary,#168e00)]/5 p-5">
          <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center">
            <div>
              <h2 className="font-bold text-[var(--supplier-heading,#004e28)]">
                ¿Ya tienes cuenta en Drooopy?
              </h2>
              <p className="mt-1 text-sm text-gray-600">
                Inicia sesión para que la cita aparezca automáticamente
                en “Mis citas”. También puedes continuar como invitado.
              </p>
            </div>
            <Link
              href={getLoginUrl(loginReturnTo)}
              className="inline-flex shrink-0 items-center justify-center gap-2 rounded-xl border border-[var(--supplier-outline,#168e00)] px-4 py-2.5 font-semibold text-[var(--supplier-accent,#168e00)]"
            >
              <LogIn size={18} />
              Iniciar sesión
            </Link>
          </div>
        </section>
      ) : null}

      <section className="rounded-3xl border border-gray-100 supplier-surface-card bg-[var(--supplier-card-background,#ffffff)] p-5 shadow-sm sm:p-6">
        <h2 className="text-xl font-bold text-gray-900">
          1. Selecciona el servicio
        </h2>

        <div className="mt-4 grid gap-3 sm:grid-cols-2">
          {services.map((service) => {
            const selected =
              service.id === selectedServiceId;

            return (
              <button
                key={service.id}
                type="button"
                onClick={() => {
                  setError(null);
                  setSelectedServiceId(service.id);
                  setSelectedSlot(null);
                  setAvailability(null);
                  setPaymentMethod("none");
                }}
                aria-pressed={selected}
                className={
                  selected
                    ? "rounded-2xl border-2 border-[var(--supplier-outline,#168e00)] bg-[var(--supplier-primary,#168e00)]/5 p-4 text-left"
                    : "rounded-2xl border border-gray-200 p-4 text-left transition hover:border-[var(--supplier-outline,#168e00)]/40"
                }
              >
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <h3 className="font-bold text-gray-900">
                      {service.name}
                    </h3>
                    {service.description ? (
                      <p className="mt-1 line-clamp-2 text-sm text-gray-500">
                        {service.description}
                      </p>
                    ) : null}
                  </div>

                  {selected ? (
                    <CheckCircle2
                      className="shrink-0 text-[var(--supplier-accent,#168e00)]"
                      size={20}
                    />
                  ) : null}
                </div>

                <div className="mt-3 flex flex-wrap gap-2 text-xs font-semibold text-gray-500">
                  <span className="rounded-full bg-gray-100 px-3 py-1">
                    {humanizeMinutes(service.duration_minutes)}
                  </span>
                  <span className="rounded-full bg-gray-100 px-3 py-1">
                    {formatMoney(service.price)}
                  </span>
                </div>
              </button>
            );
          })}
        </div>
      </section>

      <section className="rounded-3xl border border-gray-100 supplier-surface-card bg-[var(--supplier-card-background,#ffffff)] p-5 shadow-sm sm:p-6">
        <h2 className="text-xl font-bold text-gray-900">
          2. Elige fecha y horario
        </h2>

        <div className="mt-5 grid items-start gap-6 lg:grid-cols-[minmax(0,1.1fr)_minmax(300px,0.9fr)]">
          <AgendaMonthlyCalendar
            month={visibleMonth}
            availableDates={availableDates}
            selectedDate={selectedDate}
            minDate={calendarMinDate}
            maxDate={calendarMaxDate}
            loading={loadingSlots}
            onSelectDate={(date) => {
              setError(null);
              setSelectedDate(date);
              setSelectedSlot(null);
            }}
            onPreviousMonth={() => {
              setError(null);
              setVisibleMonth((current) => addMonthsToInput(current, -1));
              setSelectedDate(null);
              setSelectedSlot(null);
              setAvailability(null);
            }}
            onNextMonth={() => {
              setError(null);
              setVisibleMonth((current) => addMonthsToInput(current, 1));
              setSelectedDate(null);
              setSelectedSlot(null);
              setAvailability(null);
            }}
          />

          <div className="min-w-0 rounded-2xl supplier-surface-page bg-[var(--supplier-page-background,#f2f3f4)] p-4 sm:p-5">
            {selectedDate && availability ? (
              <div>
                <p className="text-xs font-bold uppercase tracking-[0.12em] text-[var(--supplier-accent,#168e00)]">
                  Fecha seleccionada
                </p>
                <p className="mt-1 font-[family-name:var(--font-varela-round)] text-lg font-bold text-[var(--supplier-heading,#004e28)]">
                  {formatDate(selectedDate)}
                </p>
              </div>
            ) : (
              <p className="font-semibold text-gray-700">
                Selecciona un día disponible
              </p>
            )}

            <h3 className="mt-5 text-sm font-bold text-gray-800">
              Horarios disponibles
            </h3>

            {loadingSlots ? (
              <div className="flex min-h-28 items-center gap-2 py-6 text-sm text-gray-500" role="status">
                <Loader2 size={20} className="animate-spin" aria-hidden="true" />
                Consultando horarios...
              </div>
            ) : selectedDateSlots.length && availability ? (
              <div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-2 xl:grid-cols-3">
                {selectedDateSlots.map((slot) => {
                  const selected =
                    selectedSlot?.start_at === slot.start_at;

                  return (
                    <button
                      key={slot.start_at}
                      type="button"
                      onClick={() => {
                        setError(null);
                        setSelectedSlot(slot);
                      }}
                      aria-pressed={selected}
                      aria-label={`Elegir horario ${formatSlot(slot.start_at, availability.timezone)}`}
                      className={
                        selected
                          ? "inline-flex min-h-12 items-center justify-center gap-2 rounded-xl supplier-surface-primary bg-[var(--supplier-primary-action,#168e00)] px-3 py-3 text-sm font-semibold text-[color:var(--supplier-inverse,#ffffff)] shadow-sm focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--supplier-heading,#004e28)]"
                          : "inline-flex min-h-12 items-center justify-center gap-2 rounded-xl border border-gray-200 supplier-surface-card bg-[var(--supplier-card-background,#ffffff)] px-3 py-3 text-sm font-semibold text-gray-700 transition hover:border-[var(--supplier-outline,#168e00)] hover:text-[var(--supplier-accent,#168e00)] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--supplier-outline,#168e00)]"
                      }
                    >
                      <Clock3 size={16} aria-hidden="true" />
                      {formatSlot(
                        slot.start_at,
                        availability.timezone,
                      )}
                    </button>
                  );
                })}
              </div>
            ) : availability ? (
              <div className="mt-3 rounded-xl border border-gray-200 supplier-surface-card bg-[var(--supplier-card-background,#ffffff)] p-4 text-sm text-gray-600">
                <p className="font-semibold text-gray-800">
                  No hay horarios disponibles en este periodo.
                </p>

                {calendarMaxDate &&
                addMonthsToInput(visibleMonth, 1) <= calendarMaxDate ? (
                  <button
                    type="button"
                    onClick={() => {
                      setError(null);
                      setVisibleMonth((current) =>
                        addMonthsToInput(current, 1),
                      );
                      setSelectedDate(null);
                      setSelectedSlot(null);
                    }}
                    className="mt-3 font-bold text-[var(--supplier-accent,#168e00)] underline-offset-4 hover:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--supplier-outline,#168e00)]"
                  >
                    Ver siguiente periodo
                  </button>
                ) : null}
              </div>
            ) : (
              <div className="mt-3 rounded-xl border border-gray-200 supplier-surface-card bg-[var(--supplier-card-background,#ffffff)] p-4 text-sm text-gray-500">
                Selecciona un servicio para consultar horarios.
              </div>
            )}
          </div>
        </div>
      </section>

      <section className="rounded-3xl border border-gray-100 supplier-surface-card bg-[var(--supplier-card-background,#ffffff)] p-5 shadow-sm sm:p-6">
        <h2 className="text-xl font-bold text-gray-900">
          3. Tus datos
        </h2>

        <div className="mt-5 grid gap-4 md:grid-cols-2">
          <label>
            <span className="mb-1.5 flex items-center gap-2 text-sm font-semibold text-gray-700">
              <UserRound size={16} />
              Nombre *
            </span>
            <input
              className={inputClass}
              required
              autoComplete="name"
              maxLength={255}
              value={name}
              disabled={guestBlocked}
              onChange={(event) =>
                setName(event.target.value)
              }
              placeholder="Nombre de quien asistirá"
            />
          </label>

          <label>
            <span className="mb-1.5 flex items-center gap-2 text-sm font-semibold text-gray-700">
              <Mail size={16} />
              Correo
              {guestEmailRequired ? " *" : ""}
            </span>
            <input
              type="email"
              className={inputClass}
              required={guestEmailRequired}
              autoComplete="email"
              maxLength={255}
              value={email}
              disabled={guestBlocked}
              onChange={(event) =>
                setEmail(event.target.value)
              }
              placeholder="correo@ejemplo.com"
            />
          </label>

          <label>
            <span className="mb-1.5 flex items-center gap-2 text-sm font-semibold text-gray-700">
              <Phone size={16} />
              Teléfono
            </span>
            <input
              type="tel"
              className={inputClass}
              autoComplete="tel"
              maxLength={30}
              value={phone}
              disabled={guestBlocked}
              onChange={(event) =>
                setPhone(event.target.value)
              }
              placeholder="Opcional"
            />
          </label>

          <label>
            <span className="mb-1.5 block text-sm font-semibold text-gray-700">
              Nota para el negocio
            </span>
            <input
              className={inputClass}
              maxLength={5000}
              value={notes}
              disabled={guestBlocked}
              onChange={(event) =>
                setNotes(event.target.value)
              }
              placeholder="Opcional"
            />
          </label>
        </div>
      </section>

      {legacy && availability?.accepts_payments ? (
        <AgendaPaymentMethodSelector
          allowsCash={availability.allows_cash_payment}
          onlineAvailable={availability.online_payment_available}
          value={selectedPaymentMethod}
          onChange={(method) => {
            setError(null);
            setPaymentMethod(method);
          }}
        />
      ) : null}

      {legacyUncertain ? <p role="alert" className="rounded-xl bg-amber-50 p-4 text-sm text-amber-900">Hay un intento de reserva tradicional sin resultado confirmado. Revisa tus citas o tu correo; el establecimiento puede verificarlo antes de realizar otra reserva.</p> : null}
      <section className="space-y-4 rounded-3xl border border-[var(--supplier-heading,#004e28)]/15 supplier-surface-card bg-[var(--supplier-card-background,#ffffff)] p-5 sm:p-6">
        <h2 className="text-xl font-bold text-[var(--supplier-heading,#004e28)]">Resumen de tu reservación</h2>
        {quote ? <>
          <AgendaBookingQuoteSummary quote={quote} accepted={acceptedTerms} onAccepted={setAcceptedTerms} />
        </> : selectedServiceId && !quoteState.error ? <p role="status">Consultando cotización…</p> : null}
        {quoteState.serviceId === selectedServiceId && quoteState.error ? <p role="alert" className="text-sm text-amber-900">{quoteState.error} {!legacy ? <button type="button" className="underline" onClick={() => setQuoteRefresh(n => n + 1)}>Volver a consultar</button> : null}</p> : null}
        {financialAttempt.current ? <p className="text-sm text-amber-900">Hay un intento de reservación pendiente. El siguiente clic comprobará ese mismo intento con los datos originales.</p> : null}
      </section>
      <section className="rounded-3xl border border-gray-100 supplier-surface-card bg-[var(--supplier-card-background,#ffffff)] p-5 shadow-sm sm:p-6">
        <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center">
          <div>
            <p className="text-sm font-semibold text-gray-500">
              Resumen
            </p>
            <p className="mt-1 font-bold text-gray-900">
              {selectedService?.name || "Selecciona un servicio"}
            </p>
            {selectedSlot && availability ? (
              <p className="mt-1 text-sm text-gray-500">
                {selectedDate ? formatDate(selectedDate) : ""}{" "}
                ·{" "}
                {formatSlot(
                  selectedSlot.start_at,
                  availability.timezone,
                )}
              </p>
            ) : null}
          </div>

          <button
            type="button"
            onClick={() => void submit()}
            disabled={
              saving ||
              legacyUncertain ||
              (financialAttempt.current?.requiresTermsReview === true && (!quote || quote.service_id !== financialAttempt.current.payload.service_id || !bookingTermsPayload(quote, acceptedTerms))) ||
              createdBookingId.current !== null ||
              (!recoveringAttempt && !financialAttempt.current && (
              (!quote && !legacy) ||
              (quote?.acceptance_required === true && !acceptedTerms) ||
              ((cents(quote?.initial_required) ?? BigInt(0)) > BigInt(0) && !email.trim()) ||
              loadingSlots ||
              !selectedService ||
              !selectedSlot ||
              !name.trim() ||
              (guestEmailRequired && !email.trim()) ||
              guestBlocked ||
              (legacy && availability?.accepts_payments === true && selectedPaymentMethod === "none")))
            }
            className="inline-flex items-center justify-center gap-2 rounded-xl supplier-surface-primary bg-[var(--supplier-primary-action,#168e00)] px-6 py-3.5 font-bold text-[color:var(--supplier-inverse,#ffffff)] transition hover:bg-[var(--supplier-primary-hover,#117500)] disabled:cursor-not-allowed disabled:opacity-50"
          >
            {saving ? (
              <Loader2
                size={19}
                className="animate-spin"
              />
            ) : (
              <CalendarDays size={19} />
            )}
            {financialAttempt.current ? "Consultar mismo intento" : (quote ? (cents(quote.initial_required) ?? BigInt(0)) > BigInt(0) : selectedPaymentMethod === "online") ? "Continuar al pago" : "Confirmar reservación"}
          </button>
        </div>
      </section>
    </main></SupplierTheme>
  );
}
